  ['Team cockpit: prama-agent cockpit %s --team %s']='Cockpit del equipo: prama-agent cockpit %s --team %s'
  ['Usage: prama-agent swarm stop <zone> [--team <name>|--all] | <coordinator session>']='Uso: prama-agent swarm stop <zona> [--team <nombre>|--all] | <sesión del coordinador>'
